fn main(){use std::io::{Read,Write};let mut input=std::io::stdin().lock();let mut output=std::io::stdout().lock();loop{let mut header=[0u8;8];match input.read_exact(&mut header){Ok(())=>(),Err(e)if e.kind()==std::io::ErrorKind::UnexpectedEof=>break,Err(e)=>panic!("{e}")};let function=u32::from_le_bytes(header[..4].try_into().unwrap());let length=u32::from_le_bytes(header[4..].try_into().unwrap())as usize;assert!(length<=4*1024*1024);let mut words=vec![0;length];for w in &mut words{let mut bytes=[0;4];input.read_exact(&mut bytes).unwrap();*w=u32::from_le_bytes(bytes);}let length=unsafe{ink_definition_call(function,words.as_ptr(),length as u32)};output.write_all(&length.to_le_bytes()).unwrap();if length>0{let words=unsafe{std::slice::from_raw_parts(ink_definition_result(),length as usize)};for w in words{output.write_all(&w.to_le_bytes()).unwrap();}}output.flush().unwrap();}}
